const r = $input.item.json;
const apartmentName =
  r.Apartment           ||
  (r.fields && r.fields.Apartment) ||
  r.Name                ||
  (r.fields && r.fields.Name)      ||
  'Bilinmeyen';
const icalUrl =
  r['Calendar Name']                      ||
  (r.fields && r.fields['Calendar Name']) ||
  '';
if (!icalUrl) return;
return { json: { apartmentName, icalUrl } };

const results = [];
const item = $input.item;
const icalData     = item.json.icalData;
const apartmentName = item.json.apartmentName || 'Bilinmeyen';

if (!icalData) return results;

// RFC 5545 satır katlama aç
const rawLines = icalData.split(/\r?\n/);
const lines = [];
for (const line of rawLines) {
  if ((line.startsWith(' ') || line.startsWith('\t')) && lines.length > 0) {
    lines[lines.length - 1] += line.substring(1);
  } else {
    lines.push(line);
  }
}

let evt = null;

for (const line of lines) {
  if (line === 'BEGIN:VEVENT') {
    evt = {};
  } else if (line === 'END:VEVENT') {
    if (evt?.start && evt?.end) {
      const summary = (evt.summary || '').trim();
      const sl = summary.toLowerCase();
      if (sl.includes('not available') || sl.includes('airbnb (not available)')) {
        evt = null;
        continue;
      }
      const fmt = (raw) => {
        const d = raw.replace(/T.*$/, '').replace('Z', '');
        return d.length >= 8
          ? `${d.substring(0,4)}-${d.substring(4,6)}-${d.substring(6,8)}`
          : d;
      };
      const uid = (evt.uid || '').trim();
      const kod = uid.includes('@') ? uid.split('@')[0] : uid || 'MANUAL';
      results.push({
        json: {
          Rezervasyon_Kodu: kod,
          Apartment:        apartmentName,
          Guest_Name:       summary || 'Reserved',
          Check_In:         fmt(evt.start),
          Check_Out:        fmt(evt.end),
          Source:           'Airbnb',
          Synced_At:        new Date().toISOString().split('T')[0]
        }
      });
    }
    evt = null;
  } else if (evt !== null) {
    if (line.startsWith('DTSTART'))       evt.start   = line.split(':').slice(1).join(':').trim();
    else if (line.startsWith('DTEND'))    evt.end     = line.split(':').slice(1).join(':').trim();
    else if (line.startsWith('SUMMARY:')) evt.summary = line.substring(8).trim();
    else if (line.startsWith('UID:'))     evt.uid     = line.substring(4).trim();
  }
}

return results;
